function translatePortfolio(root) {
  const targets = [...root.querySelectorAll('h3,h4,p,figcaption,dd,blockquote,.material-labels span,.ai-metrics span,.ai-screen figcaption span,nav a,footer a,.end-close,.ai-screen figcaption a')];
  targets.forEach(el => {
    if(el.dataset.bilingual || el.querySelector('.copy-en')) return;
    const source=el.innerHTML.trim();
    const english=englishCopy[source] || englishCopy[el.textContent.trim()];
    if(!english || english === source) return;
    if(el.tagName==='H3') {el.innerHTML=`<span class="copy-en" lang="en">${english}</span><span class="copy-zh" lang="zh-Hant">${source}</span>`;}
    else {
      const en=document.createElement('span'); en.className='copy-en'; en.lang='en'; en.textContent=english;
      const zh=document.createElement('span'); zh.className='copy-zh'; zh.lang='zh-Hant'; zh.innerHTML=source;
      el.replaceChildren(en,zh);
    }
    el.dataset.bilingual='true';
  });
}
function bilingualCase(html) {
  const template=document.createElement('template');template.innerHTML=html;
  translatePortfolio(template.content);return template.innerHTML;
}
